import{f as r}from"./index-C_A-ZndS.js";const n={listar(e={}){return r.get("/fornecedores",{params:e})},painel(){return r.get("/fornecedores/painel")},questionario(){return r.get("/fornecedores/questionario")},documento(){return r.get("/fornecedores/documento")},obter(e){return r.get(`/fornecedores/${e}`)},avaliacoes(e){return r.get(`/fornecedores/${e}/avaliacoes`)},criar(e){return r.post("/fornecedores",e)},atualizar(e,o){return r.patch(`/fornecedores/${e}`,o)},avaliar(e,o){return r.post(`/fornecedores/${e}/avaliar`,o)},eliminar(e){return r.delete(`/fornecedores/${e}`)}};export{n as f};
